    pct=lambda x:f'{100*x:.2f}%'
    primary=table(['Lane','Active parameters','DEV NLL, mean ± seed SD','First byte','Restricted first byte','Exact four / complete maps','Absent first byte'],[[LABEL[r['arm']],f"{r['parameters']:,}",f"{r['dev_nll_mean']:.4f} ± {r['dev_nll_sd']:.4f}",pct(r['first_accuracy']),pct(r['closed_first_accuracy']),pct(r['exact4'])+' / '+pct(r['complete_maps']),pct(r['absent_first'])] for r in ag])
